pred_cypher:
MATCH (p:Player)-[:playsPosition]->(pos:Position)
WHERE EXISTS {
  MATCH (p)-[:playsPosition]->(:Position {name: "CENTER"})
}
RETURN pos.name, count(DISTINCT p)

MATCH (p:Player)-[:playsFor]->(t:Team)
WHERE EXISTS {
  MATCH (p)-[:playsFor]->(:Team {name: "CHI"})
}
WITH t, count(DISTINCT p) AS player_count
RETURN t.name, player_count
